ervingscolor ?? "#000000").opacity(0.15), iconColor: Color(hex:viewModel.config?.servingscolor ?? "#000000"))                        }                        .frame(maxWidth: .infinity)                                                // Macros (Anillos de progreso)                        HStack(spacing: 20) {                            MacroRingView(macro: recipe.protein)                                .environmentObject(viewModel)                            MacroRingView(macro: recipe.carbs)                                .environmentObject(viewModel)                            MacroRingView(macro: recipe.fat)                                .environmentObject(viewModel)                        }                        .frame(maxWidth: .infinity)                        .padding(.vertical, 10)                                                // Tabs (Description, Ingredients, Instructions)                        HStack(spacing: 30) {                            TabButton(title: "Description", selectedTab: $selectedTab)                            TabButton(title: "Ingredients", selectedTab: $selectedTab)                            TabButton(title: "Instructions", selectedTab: $selectedTab)                        }                        .frame(maxWidth: .infinity)                        .padding(.bottom, 5)                                                Divider()                                                // Contenido Dinámico según Tab                        Group {                            if selectedTab == "Description" {                                VStack(alignment: .leading, spacing: 10) {                                    Text("Description")                                        .font(.headline)                                    Text(recipe.description)                                        .font(.body)                                        .foregroundColor(.gray)                                        .lineSpacing(4)                                }                            } else {                                Text("Contenido de \(selectedTab)...") // Placeholder para las otras tabs                                    .foregroundColor(.gray)                            }                        }                        .padding(.bottom, 50) // Espacio extra al final                                            }                    .padding(25)                    .background(Color(hex:viewModel.config?.bg_body ?? "#909090"))                    .clipShape(RoundedShape(corners: [.topLeft, .topRight], radius: 35))                    .offset(y: -40) // Efecto de superposición sobre la imagen                }            }            .edgesIgnoringSafeArea(.top)                        // 3. Barra de Navegación Flotante (Custom)            HStack {                Button(action: {                    presentationMode.wrappedValue.dismiss()                }) {                    Image(systemName: "chevron.left")                        .font(.system(size: 18, weight: .bold))                        .foregroundColor(.black)                        .padding(12)                        .background(Color.white)                        .clipShape(Circle())                        .shadow(color: .black.opacity(0.1), radius: 4, x: 0, y: 2)                }                                Spacer()                                Button(action: {                    withAnimation(.spring()) {                        isBookmarked.toggle()                    }                }) {                    Image(systemName: isBookmarked ? "bookmark.fill" : "bookmark")                        .font(.system(size: 18, weight: .bold))                        .foregroundColor(.black)                        .padding(12)                        .background(Color.white)                        .clipShape(Circle())                        .shadow(color: .black.opacity(0.1), radius: 4, x: 0, y: 2)                }            }            .padding(.horizontal)            .padding(.top, 50) // Ajuste para SafeArea        }        .navigationBarHidden(true) // Ocultamos la barra nativa para usar la nuestra    }        // Componente de Imagen de Cabecera    var headerImage: some View {        AsyncImage(url: URL(string: recipe.imageURL)) { phase in            if let image = phase.image {                image                    .resizable()                    .aspectRatio(contentMode: .fill)                    .frame(height: 250)                    .clipped()            } else {                Rectangle()                    .fill(Color.gray.opacity(0.2))                    .frame(height: 350)            }        }    }}// --- SUBCOMPONENTES UI ---// 1. Vista del Anillo de Macro// 1. Vista del Anillo de Macrostruct MacroRingView: View {    let macro: MacroData    // Necesitamos acceso al ViewModel para leer los colores de la API    @EnvironmentObject var viewModel: DesignTokensViewModel        // Lógica para elegir el color según el nombre del macro    var dynamicColor: Color {        // Valor por defecto si no hay configuración cargada        let defaultColor = macro.color                guard let config = viewModel.config else { return defaultColor }                switch macro.name {        case "Protein":            return Color(hex: config.proteinscolor.isEmpty ? "#FF69B4" : config.proteinscolor)        case "Carbs":            return Color(hex: config.carbscolor.isEmpty ? "#90EE90" : config.carbscolor)        case "Fat":            // Pediste que Fat use el color de calories            return Color(hex: config.caloriescolor.isEmpty ? "#FFA500" : config.caloriescolor)        default:            return defaultColor        }    }        var body: some View {        VStack(spacing: 8) {            ZStack {                // Círculo de fondo (más claro)                Circle()                    .stroke(dynamicColor.opacity(0.2), lineWidth: 6)                                // Círculo de progreso                Circle()                    .trim(from: 0, to: CGFloat(macro.percentage / 100))                    .stroke(dynamicColor, style: StrokeStyle(lineWidth: 6, lineCap: .round))                    .rotationEffect(.degrees(-90))                                VStack(spacing: 0) {                    Text("\(Int(macro.percentage))%")                        .font(.system(size: 14, weight: .bold))                    Text("\(String(format: "%.0fg", macro.valueGrams))")                        .font(.system(size: 10))                        .foregroundColor(.gray)                }            }            .frame(width: 65, height: 65)                        Text(macro.name)                .font(.caption)                .fontWeight(.medium)                .foregroundColor(.black)        }        .padding()        // Fondo tenue de la tarjeta usando el mismo color dinámico        .background(dynamicColor.opacity(0.05))        .cornerRadius(15)    }}// 2. Chip de Información (Calorias, Tiempo)struct InfoChip: View {    let icon: String    let text: String    let bgColor: Color    let iconColor: Color        var body: some View {        HStack(spacing: 5) {            Image(systemName: icon)                .foregroundColor(iconColor)            Text(text)                .font(.subheadline)                .fontWeight(.bold)                .foregroundColor(.black.opacity(0.8))        }        .padding(.vertical, 8)        .padding(.horizontal, 12)        .background(bgColor)        .cornerRadius(20)    }}// 3. Botón de Tabstruct TabButton: View {    let title: String    @Binding var selectedTab: String        var body: some View {        Button(action: {            withAnimation {                selectedTab = title            }        }) {            VStack(spacing: 4) {                Text(title)                    .fontWeight(selectedTab == title ? .bold : .regular)                    .foregroundColor(selectedTab == title ? .black : .gray)                                if selectedTab == title {                    Circle()                        .fill(Color.purple) // Color del indicador                        .frame(width: 6, height: 6)                } else {                    Circle()                        .fill(Color.clear)                        .frame(width: 6, height: 6)                }            }        }    }}// 4. Forma para redondear solo esquinas superioresstruct RoundedShape: Shape {    var corners: UIRectCorner    var radius: CGFloat        func path(in rect: CGRect) -> Path {        let path = UIBezierPath(            roundedRect: rect,            byRoundingCorners: corners,            cornerRadii: CGSize(width: radius, height: radius)        )        return Path(path.cgPath)    }}